INTERPRET QUERY () FOR GRAPH OlympicGraph {
  SumAccum<INT> @@count = 0;
  Events = SELECT e FROM Games:g -(IN_GAMES_REVERSE:e)-> Event:e
           WHERE g.name LIKE "%2018 Winter%" 
             AND e.sport LIKE "%Biathlon%"
             AND e.competitors > 73
           ACCUM @@count += 1;
  PRINT @@count;
}

