INTERPRET QUERY () FOR GRAPH OlympicGraph {
  MaxAccum<INT> @@max_comp = 0;
  Events = SELECT e FROM Games:g -(IN_GAMES_REVERSE:e)-> Event:e
           WHERE g.name LIKE "%2008 Summer%" AND e.sport LIKE "%Athletics%"
           ACCUM @@max_comp += e.competitors
           ORDER BY e.competitors DESC
           LIMIT 1;
  PRINT Events;
}

